-- Lot éditorial Spoontrotter généré par scripts/recipe-batches/build.mjs : 24 recettes, 13 nouveaux lieux.
-- Recettes rédigées pour l'application (adaptations éditoriales) à partir des compositions traditionnelles documentées.
-- Données source : data/recipe-batches/. Photos : Wikimedia Commons, vérifiées une à une (auteur et licence conservés).
-- Chargeur temporaire (pg_temp : disparaît à la fin de la session, jamais exposé à l'API).
create or replace function pg_temp.spoontrotter_import(batch jsonb) returns integer
language plpgsql as $fn$
declare
  r jsonb;
  p jsonb;
  ph jsonb;
  rid uuid;
  country_place uuid;
  place uuid;
  place_name text;
  region_text text;
  source_name constant text := 'Spoontrotter — adaptation éditoriale';
  author constant uuid := 'ac515660-4852-4ebd-8cb5-3348d60e06e9';
  total integer := 0;
begin
  for r in select value from jsonb_array_elements(batch) loop
    select id into country_place from public.culinary_places
      where country_code = r->>'country' and place_type = 'country' order by created_at limit 1;
    if country_place is null then
      raise exception 'Pays absent de l''atlas : %', r->>'country';
    end if;

    p := r->'place';
    if jsonb_typeof(p) = 'object' then
      insert into public.culinary_places (slug, name, country_code, place_type, parent_id, latitude, longitude, default_zoom, summary, is_active)
      values (p->>'slug', p->>'name', r->>'country', p->>'type', country_place, (p->>'lat')::float8, (p->>'lng')::float8,
              coalesce((p->>'zoom')::float8, case when p->>'type' = 'region' then 7 else 9 end), p->>'summary', true)
      on conflict (slug) do nothing;
      select id, name into place, place_name from public.culinary_places where slug = p->>'slug';
    elsif jsonb_typeof(p) = 'string' then
      select id, name into place, place_name from public.culinary_places where slug = p #>> '{}';
      if place is null then
        raise exception 'Lieu absent de l''atlas : %', p #>> '{}';
      end if;
    else
      place := country_place;
      place_name := null;
    end if;

    region_text := coalesce(r->>'region', place_name);
    rid := md5('spoontrotter:recipe:' || (r->>'slug'))::uuid;
    ph := r->'photo';

    insert into public.recipes (id, author_id, title, original_title, slug, description, excerpt, source_language, country_code, region,
      category, authenticity, status, difficulty, prep_minutes, cook_minutes, servings, published_at, primary_place_id,
      is_editorial, is_borderless, source_name, source_url, source_notes)
    values (rid, author, r->>'title', r->>'original', r->>'slug', r->>'desc', r->>'desc', 'fr', r->>'country', region_text,
      r->>'cat', coalesce(r->>'auth', 'adapted')::public.recipe_authenticity, 'published', (r->>'diff')::public.recipe_difficulty,
      (r->>'prep')::int, (r->>'cook')::int, (r->>'serv')::numeric, now(), place,
      true, false, source_name, ph->>'page',
      'Recette éditoriale rédigée pour l’application à partir de la composition traditionnelle documentée du plat.')
    on conflict (id) do update set title = excluded.title, original_title = excluded.original_title, description = excluded.description,
      excerpt = excluded.excerpt, country_code = excluded.country_code, region = excluded.region, category = excluded.category,
      difficulty = excluded.difficulty, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes,
      servings = excluded.servings, primary_place_id = excluded.primary_place_id, source_url = excluded.source_url, updated_at = now();

    delete from public.recipe_ingredients where recipe_id = rid;
    insert into public.recipe_ingredients (recipe_id, position, name, quantity, unit, note)
    select rid, (t.o - 1)::int, t.e->>0, (t.e->>1)::numeric, t.e->>2, t.e->>3
    from jsonb_array_elements(r->'ing') with ordinality as t(e, o);

    delete from public.recipe_steps where recipe_id = rid;
    insert into public.recipe_steps (recipe_id, position, instruction)
    select rid, (t.o - 1)::int, t.s from jsonb_array_elements_text(r->'steps') with ordinality as t(s, o);

    delete from public.recipe_title_translations where recipe_id = rid;
    insert into public.recipe_title_translations (recipe_id, language_code, title, model) values
      (rid, 'fr', r->>'title', 'editorial-seed'),
      (rid, 'en', r->>'en', 'editorial-reviewed'),
      (rid, 'es', r->>'es', 'editorial-reviewed');

    delete from public.recipe_locations where recipe_id = rid;
    insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, place, 'origin', true);
    if place <> country_place then
      insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, country_place, 'origin', false);
    end if;

    delete from public.place_specialties where recipe_id = rid;
    insert into public.place_specialties (place_id, recipe_id, name, description, origin_note, is_signature, sort_order, source_name, source_url)
    values (place, rid, r->>'original', r->>'desc', coalesce(region_text, (select name from public.culinary_places where id = country_place)),
            place <> country_place, 10, source_name, ph->>'page');

    delete from public.recipe_images where recipe_id = rid and source_type = 'external_licensed';
    if jsonb_typeof(ph) = 'object' then
      insert into public.recipe_images (recipe_id, source_type, status, external_url, alt_text, source_name, source_page_url,
        photographer_name, license_name, license_url, attribution_text, is_primary, is_representative, moderation_notes)
      values (rid, 'external_licensed', 'ready', ph->>'url', r->>'title', coalesce(ph->>'source', 'Wikimedia Commons'), ph->>'page',
        nullif(ph->>'author', ''), ph->>'license', nullif(ph->>'licenseUrl', ''),
        'Photo : ' || coalesce(nullif(ph->>'author', ''), 'auteur inconnu') || ' · ' || (ph->>'license') || ' · ' || coalesce(ph->>'source', 'Wikimedia Commons'),
        true, true, 'Photo libre vérifiée à l’œil : le fichier représente ce plat.');
    end if;

    total := total + 1;
  end loop;
  return total;
end;
$fn$;
select pg_temp.spoontrotter_import($batch$[{"slug":"rogan-josh-kashmir","country":"IN","original":"Rogan josh","title":"Rogan josh du Cachemire (agneau braisé au piment et yaourt)","en":"Kashmiri rogan josh (aromatic braised lamb)","es":"Rogan josh de Cachemira (cordero estofado aromático)","desc":"Agneau braisé dans une sauce rouge parfumée au piment du Cachemire, fenouil, gingembre sec et yaourt, plat du wazwan cachemiri.","cat":"Ragoût","diff":"medium","prep":20,"cook":90,"serv":6,"place":{"slug":"in-kashmir","name":"Cachemire","type":"region","lat":34.08,"lng":74.8,"summary":"Vallée himalayenne (Srinagar) du wazwan : rogan josh, gushtaba, yakhni."},"ing":[["Épaule d’agneau avec os",1.2,"kg","en morceaux"],["Yaourt nature",250,"g","fouetté"],["Piment du Cachemire en poudre",2,"c. à soupe",null],["Fenouil moulu",2,"c. à thé",null],["Gingembre sec moulu",1,"c. à thé",null],["Cardamome verte et noire",6,null,null],["Clous de girofle",4,null,null],["Cannelle",1,"bâton",null],["Ghee ou huile de moutarde",4,"c. à soupe",null],["Asafoetida",1,"pincée",null],["Sel",1.5,"c. à thé",null]],"steps":["Chauffer le ghee et y faire éclater cardamomes, girofle, cannelle et asafoetida.","Ajouter l’agneau et le saisir 10 minutes jusqu’à coloration.","Délayer le piment dans un peu d’eau et l’ajouter avec le sel.","Incorporer le yaourt peu à peu en remuant pour qu’il ne tranche pas.","Ajouter fenouil, gingembre sec et 300 ml d’eau; couvrir et mijoter 1 heure.","Réduire jusqu’à ce que l’huile rouge remonte; servir avec du riz."],"photo":{"file":"File:Rogan Josh.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ee/Rogan_Josh.JPG/1280px-Rogan_Josh.JPG","page":"https://commons.wikimedia.org/wiki/File:Rogan_Josh.JPG","author":"Miansari66","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"Wikimedia Commons"}},{"slug":"vada-pav-mumbai","country":"IN","original":"Vada pav","title":"Vada pav de Mumbai (beignet de pomme de terre dans un petit pain)","en":"Mumbai vada pav","es":"Vada pav de Bombay","desc":"Beignet de purée de pommes de terre épicée enrobé de pâte de pois chiches, glissé dans un pain pav avec chutneys à l’ail et à la coriandre.","cat":"Cuisine de rue","diff":"medium","prep":30,"cook":20,"serv":6,"place":{"slug":"in-mumbai","name":"Mumbai","type":"city","lat":19.076,"lng":72.8777,"summary":"Métropole du Maharashtra : vada pav, pav bhaji, bhel puri sur la plage de Chowpatty."},"ing":[["Pommes de terre",600,"g","cuites et écrasées"],["Graines de moutarde",1,"c. à thé",null],["Feuilles de curry",10,null,null],["Gingembre, ail et piment vert",2,"c. à soupe","en pâte"],["Curcuma",0.5,"c. à thé",null],["Farine de pois chiches (besan)",150,"g",null],["Huile de friture",1,"l",null],["Pains pav",6,null,null],["Chutney sec à l’ail",4,"c. à soupe",null],["Chutney vert coriandre-menthe",4,"c. à soupe",null],["Sel",1.5,"c. à thé",null]],"steps":["Faire éclater moutarde et feuilles de curry dans un peu d’huile, ajouter la pâte gingembre-ail-piment et le curcuma.","Mélanger avec les pommes de terre et le sel; former 6 boules.","Préparer une pâte épaisse de besan, eau, sel et curcuma.","Enrober les boules et les frire à 180 °C jusqu’à ce qu’elles soient dorées.","Ouvrir les pav et tartiner des deux chutneys.","Glisser un vada chaud dans chaque pain et servir avec un piment vert frit."],"photo":{"file":"File:Indian Food snacks prasad-101.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Indian_Food_snacks_prasad-101.jpg/1280px-Indian_Food_snacks_prasad-101.jpg","page":"https://commons.wikimedia.org/wiki/File:Indian_Food_snacks_prasad-101.jpg","author":"Prasad SR","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"pav-bhaji-mumbai","country":"IN","original":"Pav bhaji","title":"Pav bhaji de Mumbai (purée de légumes épicée et petits pains beurrés)","en":"Mumbai pav bhaji","es":"Pav bhaji de Bombay","desc":"Légumes écrasés et mijotés au beurre avec le mélange d’épices pav bhaji masala, servis avec des pains pav grillés au beurre, oignon cru et citron.","cat":"Cuisine de rue","diff":"easy","prep":20,"cook":40,"serv":4,"place":{"slug":"in-mumbai","name":"Mumbai","type":"city","lat":19.076,"lng":72.8777,"summary":"Métropole du Maharashtra : vada pav, pav bhaji, bhel puri sur la plage de Chowpatty."},"ing":[["Pommes de terre",3,null,"cuites"],["Chou-fleur",200,"g","cuit"],["Petits pois",100,"g",null],["Poivron vert",1,null,"haché"],["Tomates",3,null,"hachées"],["Oignons",2,null,"hachés"],["Pav bhaji masala",2,"c. à soupe",null],["Piment du Cachemire",1,"c. à thé",null],["Beurre",80,"g",null],["Pains pav",8,null,null],["Citron",1,null,null],["Coriandre",1,"bouquet",null]],"steps":["Faire fondre la moitié du beurre et y cuire un oignon et le poivron.","Ajouter les tomates et cuire jusqu’à compote.","Ajouter les légumes cuits, les épices et 150 ml d’eau.","Écraser au pilon directement dans la poêle et mijoter 15 minutes.","Griller les pav coupés en deux dans le reste du beurre.","Servir la bhaji avec un morceau de beurre, oignon cru, coriandre, citron et les pav."],"photo":{"file":"File:Butter Pav Bhaji.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/9/93/Butter_Pav_Bhaji.jpg","page":"https://commons.wikimedia.org/wiki/File:Butter_Pav_Bhaji.jpg","author":"Ojas91196","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"masala-dosa-udupi","country":"IN","original":"Masala dosa","title":"Masala dosa d’Udupi (crêpe fermentée garnie de pommes de terre)","en":"Udupi masala dosa","es":"Masala dosa de Udupi","desc":"Grande crêpe croustillante de riz et lentilles urad fermentés, garnie de pommes de terre aux graines de moutarde, servie avec sambar et chutney de coco.","cat":"Petit-déjeuner","diff":"hard","prep":40,"cook":30,"serv":6,"place":{"slug":"in-udupi","name":"Udupi","type":"city","lat":13.3409,"lng":74.7421,"summary":"Ville du Karnataka célèbre pour sa cuisine végétarienne des temples et ses dosas."},"ing":[["Riz",300,"g","trempé 6 heures"],["Lentilles urad dal",100,"g","trempées 6 heures"],["Graines de fenugrec",0.5,"c. à thé",null],["Pommes de terre",600,"g","cuites"],["Oignons",2,null,"émincés"],["Graines de moutarde",1,"c. à thé",null],["Chana dal",1,"c. à soupe",null],["Feuilles de curry",10,null,null],["Curcuma",0.5,"c. à thé",null],["Piments verts",2,null,null],["Ghee ou huile",4,"c. à soupe",null],["Sel",2,"c. à thé",null]],"steps":["Mixer riz, urad et fenugrec avec un peu d’eau en pâte lisse; saler et laisser fermenter 12 heures.","Faire éclater moutarde, chana dal et feuilles de curry dans l’huile.","Ajouter oignons, piments, curcuma, puis les pommes de terre écrasées grossièrement.","Étaler une louche de pâte en spirale très fine sur une plaque chaude.","Arroser de ghee et cuire jusqu’à ce que le dessous soit doré et croustillant.","Garnir de pommes de terre, rouler et servir avec sambar et chutney de coco."],"photo":{"file":"File:Masala dosa 01.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/43/Masala_dosa_01.jpg/1280px-Masala_dosa_01.jpg","page":"https://commons.wikimedia.org/wiki/File:Masala_dosa_01.jpg","author":"Marajozkee","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"pork-vindaloo-goa","country":"IN","original":"Vindalho (pork vindaloo)","title":"Vindaloo de porc de Goa (porc mariné au vinaigre, ail et piment)","en":"Goan pork vindaloo","es":"Vindaloo de cerdo de Goa","desc":"Héritier de la carne de vinha d’alhos portugaise : porc mariné au vinaigre, ail et piments du Cachemire, cuit longuement jusqu’à une sauce acidulée et relevée.","cat":"Ragoût","diff":"medium","prep":30,"cook":90,"serv":6,"place":{"slug":"in-goa","name":"Goa","type":"region","lat":15.3,"lng":74.1,"summary":"État côtier lusophone d’héritage : curry de poisson, vindaloo, xacuti et bebinca."},"ing":[["Échine de porc",1,"kg","en cubes"],["Piments rouges secs du Cachemire",12,null,null],["Vinaigre de palme ou de cidre",120,"ml",null],["Ail",10,"gousses",null],["Gingembre",30,"g",null],["Cumin",1,"c. à thé",null],["Poivre noir",1,"c. à thé",null],["Clous de girofle",6,null,null],["Cannelle",1,"bâton",null],["Oignons",2,null,"émincés"],["Sucre",1,"c. à thé",null],["Sel",2,"c. à thé",null]],"steps":["Faire tremper les piments dans le vinaigre 30 minutes.","Mixer piments, vinaigre, ail, gingembre et épices en pâte.","Mariner le porc dans cette pâte au moins 6 heures.","Faire dorer les oignons, ajouter le porc et sa marinade.","Mijoter 1 heure à couvert en ajoutant un peu d’eau au besoin.","Ajuster sel et sucre; le vindaloo est meilleur le lendemain."],"photo":{"file":"File:Vindalho.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/2/28/Vindalho.jpg","page":"https://commons.wikimedia.org/wiki/File:Vindalho.jpg","author":"Adriao","license":"CC BY 2.5","licenseUrl":"https://creativecommons.org/licenses/by/2.5","source":"Wikimedia Commons"}},{"slug":"litti-chokha-bihar","country":"IN","original":"Litti chokha","title":"Litti chokha du Bihar (boules de blé farcies au sattu, purée d’aubergine)","en":"Bihari litti chokha","es":"Litti chokha de Bihar","desc":"Boules de pâte de blé farcies de sattu (farine de pois chiches grillés) épicé, cuites sur les braises et trempées dans le ghee, servies avec une purée d’aubergine, tomate et pomme de terre grillées.","cat":"Plat principal","diff":"medium","prep":40,"cook":40,"serv":4,"place":{"slug":"in-bihar","name":"Bihar","type":"region","lat":25.6,"lng":85.1,"summary":"État de la plaine du Gange (Patna), patrie du litti chokha et du sattu."},"ing":[["Farine de blé complète (atta)",300,"g",null],["Sattu",200,"g",null],["Ail, gingembre et piment vert",2,"c. à soupe","hachés"],["Graines d’ajwain et de nigelle",1,"c. à thé",null],["Jus de citron",2,"c. à soupe",null],["Huile de moutarde",3,"c. à soupe",null],["Aubergine",1,null,"grosse"],["Tomates",2,null,null],["Pommes de terre",2,null,"cuites"],["Oignon",1,null,"haché"],["Ghee",80,"g","fondu"],["Sel",2,"c. à thé",null]],"steps":["Pétrir l’atta avec sel, eau et un peu d’huile; reposer 20 minutes.","Mélanger sattu, aromates, graines, citron, huile de moutarde et sel avec un peu d’eau.","Farcir des boules de pâte avec ce mélange et les refermer.","Cuire les litti sur braises ou au four à 200 °C 30 minutes en les retournant.","Griller aubergine et tomates à la flamme, les peler et les écraser avec pommes de terre, oignon, ail, piment et huile de moutarde.","Tremper les litti chauds dans le ghee et servir avec le chokha."],"photo":{"file":"File:Litti chokha of bihar.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/9/93/Litti_chokha_of_bihar.jpg","page":"https://commons.wikimedia.org/wiki/File:Litti_chokha_of_bihar.jpg","author":"ksandip","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"dal-baati-churma","country":"IN","original":"Dal baati churma","title":"Dal baati churma du Rajasthan (boules de blé, dal et miettes sucrées)","en":"Rajasthani dal baati churma","es":"Dal baati churma de Rajastán","desc":"Boules de blé cuites au four et trempées dans le ghee, servies avec un dal de cinq lentilles et le churma, miettes de baati sucrées au jaggery.","cat":"Plat principal","diff":"medium","prep":40,"cook":60,"serv":6,"place":{"slug":"in-rajasthan","name":"Rajasthan","type":"region","lat":26.9,"lng":73.8,"summary":"État désertique (Jaipur, Jodhpur, Udaipur) : dal baati, laal maas, ker sangri."},"ing":[["Farine de blé complète",500,"g",null],["Semoule fine",50,"g",null],["Ghee",250,"g",null],["Ajwain",1,"c. à thé",null],["Lentilles mélangées (toor, chana, moong, urad, masoor)",250,"g",null],["Tomates",2,null,null],["Cumin, curcuma, piment, garam masala",1,"portion",null],["Jaggery ou sucre roux",100,"g",null],["Cardamome",0.5,"c. à thé",null],["Sel",2,"c. à thé",null]],"steps":["Pétrir farine, semoule, ajwain, sel et 80 g de ghee avec de l’eau en pâte ferme.","Façonner des boules et les cuire 35 minutes à 200 °C; les fendre et les tremper dans le ghee chaud.","Cuire les lentilles, puis les assaisonner d’un tadka de cumin, tomates et épices dans le ghee.","Pour le churma, émietter 3 baati et les mélanger avec ghee, jaggery et cardamome.","Disposer baati, dal et churma dans l’assiette.","Arroser généreusement de ghee avant de servir."],"photo":{"file":"File:Daal Baati Choorma.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e4/Daal_Baati_Choorma.jpg/1280px-Daal_Baati_Choorma.jpg","page":"https://commons.wikimedia.org/wiki/File:Daal_Baati_Choorma.jpg","author":"Harshitdenovo","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"chole-bhature-delhi","country":"IN","original":"Chole bhature","title":"Chole bhature de Delhi (pois chiches épicés et pains frits gonflés)","en":"Delhi chole bhature","es":"Chole bhature de Delhi","desc":"Pois chiches cuits au thé noir pour leur couleur sombre et relevés d’épices, servis avec les bhature, pains levés frits qui gonflent comme des ballons.","cat":"Petit-déjeuner","diff":"medium","prep":30,"cook":60,"serv":4,"place":"in-delhi","ing":[["Pois chiches secs",250,"g","trempés une nuit"],["Sachet de thé noir",1,null,null],["Oignons",2,null,"hachés"],["Tomates",3,null,"hachées"],["Chole masala",2,"c. à soupe",null],["Poudre d’amchur (mangue sèche)",1,"c. à thé",null],["Farine",300,"g",null],["Yaourt",100,"g",null],["Semoule fine",2,"c. à soupe",null],["Levure chimique",1,"c. à thé",null],["Huile de friture",1,"l",null],["Sel",2,"c. à thé",null]],"steps":["Pétrir farine, semoule, yaourt, levure, sel et un peu d’eau; reposer 2 heures.","Cuire les pois chiches à l’autocuiseur avec le sachet de thé jusqu’à tendreté.","Faire revenir oignons puis tomates avec le chole masala.","Ajouter les pois chiches, l’amchur et un peu d’eau de cuisson; mijoter 20 minutes.","Étaler des disques de pâte et les frire à 190 °C en appuyant pour qu’ils gonflent.","Servir les chole avec les bhature, oignons crus et pickles."],"photo":{"file":"File:A Plate of Chole Bhature.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/58/A_Plate_of_Chole_Bhature.JPG/1280px-A_Plate_of_Chole_Bhature.JPG","page":"https://commons.wikimedia.org/wiki/File:A_Plate_of_Chole_Bhature.JPG","author":"Lady adi","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"kosha-mangsho","country":"IN","original":"Kosha mangsho","title":"Kosha mangsho bengali (mouton longuement rissolé aux épices)","en":"Bengali kosha mangsho","es":"Kosha mangsho bengalí","desc":"Mouton mariné au yaourt et à l’huile de moutarde puis « koshano », rissolé lentement jusqu’à une sauce épaisse et brune, plat dominical de Calcutta servi avec des luchi.","cat":"Ragoût","diff":"medium","prep":20,"cook":120,"serv":6,"place":"in-west-bengal","ing":[["Mouton avec os",1,"kg",null],["Yaourt",200,"g",null],["Huile de moutarde",100,"ml",null],["Oignons",4,null,"émincés"],["Pâte gingembre-ail",3,"c. à soupe",null],["Curcuma",1,"c. à thé",null],["Piment rouge",2,"c. à thé",null],["Cumin moulu",1,"c. à thé",null],["Sucre",1,"c. à thé",null],["Garam masala bengali",1,"c. à thé",null],["Pommes de terre",2,null,"facultatif"],["Sel",2,"c. à thé",null]],"steps":["Mariner le mouton avec yaourt, pâte gingembre-ail, curcuma, piment et 2 cuillères d’huile de moutarde 4 heures.","Chauffer l’huile jusqu’à fumée, ajouter le sucre puis les oignons et les dorer profondément.","Ajouter la viande et sa marinade.","Rissoler à feu moyen 45 minutes en remuant sans ajouter d’eau.","Ajouter un peu d’eau chaude et cuire à couvert 45 minutes de plus.","Finir au garam masala; servir avec des luchi ou du riz."],"photo":{"file":"File:Kosha Mangsho.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/37/Kosha_Mangsho.jpg/1280px-Kosha_Mangsho.jpg","page":"https://commons.wikimedia.org/wiki/File:Kosha_Mangsho.jpg","author":"Sumit Surai","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"misal-pav-kolhapur","country":"IN","original":"Misal pav","title":"Misal pav de Kolhapur (curry de haricots germés très relevé)","en":"Kolhapuri misal pav","es":"Misal pav de Kolhapur","desc":"Curry piquant de haricots papillons germés (matki), nappé d’un bouillon rouge épicé (kat), de farsan croustillant, d’oignon et de citron, servi avec des pav.","cat":"Petit-déjeuner","diff":"medium","prep":20,"cook":40,"serv":4,"place":{"slug":"in-kolhapur","name":"Kolhapur","type":"city","lat":16.705,"lng":74.2433,"summary":"Ville du sud du Maharashtra réputée pour sa cuisine très épicée (misal, tambda rassa)."},"ing":[["Haricots matki germés",300,"g",null],["Oignons",2,null,"hachés"],["Tomates",2,null,"hachées"],["Noix de coco sèche râpée",50,"g","grillée"],["Pâte gingembre-ail",1,"c. à soupe",null],["Kolhapuri masala ou piment",2,"c. à soupe",null],["Graines de moutarde et feuilles de curry",1,"portion",null],["Farsan (mélange croustillant)",150,"g",null],["Pains pav",8,null,null],["Citrons",2,null,null],["Coriandre",1,"bouquet",null],["Sel",1.5,"c. à thé",null]],"steps":["Mixer un oignon grillé, la coco grillée et la pâte gingembre-ail en pâte.","Faire éclater moutarde et curry dans l’huile, ajouter l’autre oignon et les tomates.","Ajouter la pâte et le masala; frire jusqu’à ce que l’huile se sépare.","Ajouter les matki et 800 ml d’eau; cuire 20 minutes jusqu’à un curry fluide et rouge.","Servir dans un bol garni de farsan, oignon cru, coriandre et citron.","Accompagner de pav et d’un supplément de kat (bouillon pimenté)."],"photo":{"file":"File:Kolhapuri Misal Pav.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a0/Kolhapuri_Misal_Pav.jpg/1280px-Kolhapuri_Misal_Pav.jpg","page":"https://commons.wikimedia.org/wiki/File:Kolhapuri_Misal_Pav.jpg","author":"Ankushkr2020","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"bun-cha-hanoi","country":"VN","original":"Bún chả","title":"Bún chả de Hanoï (porc grillé, vermicelles et sauce nuoc cham)","en":"Hanoi bún chả (grilled pork with rice noodles)","es":"Bún chả de Hanói (cerdo a la parrilla con fideos)","desc":"Boulettes et tranches de porc grillées au charbon servies dans une sauce aigre-douce au nuoc-mâm avec papaye verte, vermicelles de riz et herbes fraîches.","cat":"Plat principal","diff":"medium","prep":40,"cook":20,"serv":4,"place":"vn-hanoi","ing":[["Poitrine de porc",400,"g","en fines tranches"],["Porc haché",400,"g",null],["Nuoc-mâm",6,"c. à soupe",null],["Sucre",5,"c. à soupe",null],["Échalotes et ail",4,"c. à soupe","hachés"],["Caramel ou mélasse",1,"c. à soupe",null],["Vinaigre de riz ou jus de lime",4,"c. à soupe",null],["Papaye verte et carotte",150,"g","en fines lamelles"],["Vermicelles de riz (bún)",400,"g",null],["Herbes (laitue, menthe, périlla, coriandre)",2,"gros bouquet",null],["Piment et ail",1,"portion",null]],"steps":["Mariner tranches et haché de porc avec nuoc-mâm, sucre, échalotes, ail et caramel 1 heure.","Façonner de petites galettes avec le haché.","Griller le porc sur le charbon jusqu’à caramélisation.","Préparer la sauce : 500 ml d’eau tiède, nuoc-mâm, sucre et vinaigre; y ajouter papaye et carotte.","Plonger le porc grillé dans des bols de sauce.","Servir avec vermicelles, herbes, ail et piment."],"photo":{"file":"File:Bun-cha-hanoi.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7f/Bun-cha-hanoi.jpg/1280px-Bun-cha-hanoi.jpg","page":"https://commons.wikimedia.org/wiki/File:Bun-cha-hanoi.jpg","author":"Valentin Orange","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"bun-bo-hue","country":"VN","original":"Bún bò Huế","title":"Bún bò Huế (soupe de nouilles au bœuf et à la citronnelle)","en":"Bún bò Huế (spicy lemongrass beef noodle soup)","es":"Bún bò Huế (sopa picante de fideos con ternera)","desc":"Bouillon de jarret de bœuf et de porc parfumé à la citronnelle et à la pâte de crevettes fermentée, relevé d’huile pimentée, avec nouilles rondes épaisses, spécialité de l’ancienne cité impériale de Huế.","cat":"Soupe","diff":"medium","prep":30,"cook":180,"serv":6,"place":{"slug":"vn-hue","name":"Huế","type":"city","lat":16.4637,"lng":107.5909,"summary":"Ancienne capitale impériale du centre du Vietnam : bún bò, bánh khoái, cuisine de cour."},"ing":[["Jarret de bœuf",800,"g",null],["Jarret de porc",600,"g",null],["Citronnelle",6,"tiges","écrasées"],["Pâte de crevettes fermentée (mắm ruốc)",2,"c. à soupe",null],["Nuoc-mâm",4,"c. à soupe",null],["Sucre",1,"c. à soupe",null],["Paprika et piment en poudre",2,"c. à soupe",null],["Huile",4,"c. à soupe",null],["Nouilles de riz rondes épaisses",600,"g",null],["Oignon, ciboule, coriandre",1,"portion",null],["Fleur de bananier et herbes",1,"portion",null]],"steps":["Blanchir les viandes, les rincer puis les cuire 2 h 30 dans 4 litres d’eau avec la citronnelle.","Délayer la pâte de crevettes dans de l’eau, laisser décanter et verser le liquide clair dans le bouillon.","Faire une huile pimentée : chauffer l’huile avec citronnelle hachée, paprika et piment.","Assaisonner le bouillon de nuoc-mâm, sucre et d’une partie de l’huile pimentée.","Cuire les nouilles et les répartir dans les bols avec viandes tranchées.","Verser le bouillon brûlant, garnir d’oignon, herbes et fleur de bananier."],"photo":{"file":"File:Bun Bo Hue - Pho Huang Bakao, Springvale.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/d/d0/Bun_Bo_Hue_-_Pho_Huang_Bakao%2C_Springvale.jpg","page":"https://commons.wikimedia.org/wiki/File:Bun_Bo_Hue_-_Pho_Huang_Bakao,_Springvale.jpg","author":"avlxyz","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"com-tam-saigon","country":"VN","original":"Cơm tấm","title":"Cơm tấm de Saïgon (riz brisé, côtelette de porc grillée)","en":"Saigon cơm tấm (broken rice with grilled pork chop)","es":"Cơm tấm de Saigón (arroz partido con chuleta)","desc":"Riz brisé servi avec une côtelette de porc grillée à la citronnelle, peau de porc effilochée, flan aux œufs (chả trứng) et nuoc-mâm sucré, petit-déjeuner de Hô-Chi-Minh-Ville.","cat":"Riz","diff":"medium","prep":30,"cook":30,"serv":4,"place":{"slug":"vn-ho-chi-minh","name":"Hô-Chi-Minh-Ville (Saïgon)","type":"city","lat":10.7769,"lng":106.7009,"summary":"Métropole du Sud du Vietnam : cơm tấm, bánh mì, hủ tiếu et gỏi cuốn."},"ing":[["Riz brisé",400,"g",null],["Côtelettes de porc fines",4,null,null],["Citronnelle",2,"tiges","hachées"],["Ail et échalote",2,"c. à soupe","hachés"],["Nuoc-mâm",5,"c. à soupe",null],["Sucre",4,"c. à soupe",null],["Miel",1,"c. à soupe",null],["Œufs",3,null,"pour le flan"],["Porc haché",150,"g","pour le flan"],["Ciboule à l’huile (mỡ hành)",3,"c. à soupe",null],["Concombre, tomate et pickles",1,"portion",null]],"steps":["Mariner les côtelettes avec citronnelle, ail, échalote, nuoc-mâm, sucre et miel 2 heures.","Cuire le riz brisé.","Mélanger œufs, porc haché et un peu de nuoc-mâm; cuire à la vapeur 20 minutes pour le chả trứng.","Griller les côtelettes au charbon jusqu’à caramélisation.","Préparer un nuoc-mâm dilué : eau, sucre, citron, ail, piment.","Servir riz, côtelette, flan, ciboule à l’huile et crudités, arrosés de sauce."],"photo":{"file":"File:Cơm Tấm Bì Sườn Chả.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/b/b9/C%C6%A1m_T%E1%BA%A5m_B%C3%AC_S%C6%B0%E1%BB%9Dn_Ch%E1%BA%A3.jpg","page":"https://commons.wikimedia.org/wiki/File:C%C6%A1m_T%E1%BA%A5m_B%C3%AC_S%C6%B0%E1%BB%9Dn_Ch%E1%BA%A3.jpg","author":"Charles Haynes","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"banh-mi-saigon","country":"VN","original":"Bánh mì","title":"Bánh mì de Saïgon (sandwich baguette au porc et pickles)","en":"Saigon bánh mì","es":"Bánh mì de Saigón","desc":"Baguette légère et croustillante garnie de pâté, mayonnaise, charcuteries vietnamiennes ou porc grillé, carotte et daïkon marinés, concombre, coriandre et piment.","cat":"Cuisine de rue","diff":"easy","prep":30,"cook":15,"serv":4,"place":{"slug":"vn-ho-chi-minh","name":"Hô-Chi-Minh-Ville (Saïgon)","type":"city","lat":10.7769,"lng":106.7009,"summary":"Métropole du Sud du Vietnam : cơm tấm, bánh mì, hủ tiếu et gỏi cuốn."},"ing":[["Baguettes vietnamiennes",4,null,null],["Pâté de foie",120,"g",null],["Mayonnaise",4,"c. à soupe",null],["Porc grillé ou chả lụa (saucisson)",300,"g","en tranches"],["Carotte",1,null,"en julienne"],["Daïkon",150,"g","en julienne"],["Vinaigre et sucre",4,"c. à soupe","pour les pickles"],["Concombre",1,null,"en bâtonnets"],["Coriandre",1,"bouquet",null],["Piment",2,null,"émincés"],["Sauce Maggi",1,"c. à soupe",null]],"steps":["Mariner carotte et daïkon 30 minutes dans vinaigre, sucre, sel et eau tiède.","Réchauffer les baguettes au four pour les rendre croustillantes.","Les ouvrir et tartiner de pâté et de mayonnaise.","Garnir de viande, d’un trait de Maggi, puis des pickles égouttés.","Ajouter concombre, coriandre et piment.","Servir aussitôt."],"photo":{"file":"File:Banh mi thit Nhu Lan.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/4/4f/Banh_mi_thit_Nhu_Lan.jpg","page":"https://commons.wikimedia.org/wiki/File:Banh_mi_thit_Nhu_Lan.jpg","author":"Charles Haynes","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"mi-quang","country":"VN","original":"Mì Quảng","title":"Mì Quảng (nouilles de riz jaunes au porc et crevettes, peu de bouillon)","en":"Mì Quảng (Quảng Nam turmeric noodles)","es":"Mì Quảng (fideos de arroz con cerdo y gambas)","desc":"Larges nouilles de riz au curcuma servies avec un fond de bouillon concentré, porc, crevettes, œuf de caille, cacahuètes grillées, herbes et galette de riz au sésame.","cat":"Plat principal","diff":"medium","prep":30,"cook":45,"serv":4,"place":{"slug":"vn-quang-nam","name":"Quảng Nam","type":"region","lat":15.57,"lng":108,"summary":"Province du centre du Vietnam (Hội An, Tam Kỳ), berceau du mì Quảng."},"ing":[["Nouilles de riz larges jaunes",500,"g",null],["Poitrine de porc",300,"g","en tranches"],["Crevettes",300,"g",null],["Bouillon d’os de porc",1,"l",null],["Curcuma",1,"c. à thé",null],["Échalotes et ail",3,"c. à soupe","hachés"],["Nuoc-mâm",3,"c. à soupe",null],["Œufs de caille durs",8,null,null],["Cacahuètes grillées",60,"g",null],["Galettes de riz au sésame (bánh tráng mè)",4,null,null],["Herbes et salade",2,"bouquet",null]],"steps":["Faire revenir échalotes et ail avec le curcuma.","Ajouter porc et crevettes, assaisonner de nuoc-mâm et saisir.","Mouiller avec le bouillon et mijoter 20 minutes avec les œufs de caille.","Blanchir les nouilles et les mettre sur un lit d’herbes dans les bols.","Couvrir de garniture et d’un peu de bouillon seulement (il ne doit pas noyer les nouilles).","Parsemer de cacahuètes et servir avec la galette de riz grillée à émietter."],"photo":{"file":"File:Mì Quảng, Da Nang, Vietnam.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/M%C3%AC_Qu%E1%BA%A3ng%2C_Da_Nang%2C_Vietnam.jpg/1280px-M%C3%AC_Qu%E1%BA%A3ng%2C_Da_Nang%2C_Vietnam.jpg","page":"https://commons.wikimedia.org/wiki/File:M%C3%AC_Qu%E1%BA%A3ng,_Da_Nang,_Vietnam.jpg","author":"Christopher Crouzet","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"cha-ca-la-vong","country":"VN","original":"Chả cá Lã Vọng","title":"Chả cá Lã Vọng de Hanoï (poisson au curcuma et à l’aneth)","en":"Hanoi chả cá Lã Vọng (turmeric fish with dill)","es":"Chả cá Lã Vọng de Hanói (pescado con cúrcuma y eneldo)","desc":"Poisson mariné au curcuma et au galanga, grillé puis fini à table dans une poêle avec beaucoup d’aneth et de ciboule, servi avec vermicelles, cacahuètes et mắm tôm.","cat":"Poisson","diff":"medium","prep":30,"cook":20,"serv":4,"place":"vn-hanoi","ing":[["Filets de poisson blanc ferme",600,"g","en morceaux"],["Curcuma frais ou moulu",1,"c. à soupe",null],["Galanga",1,"c. à soupe","râpé"],["Yaourt ou riz fermenté",2,"c. à soupe",null],["Nuoc-mâm",2,"c. à soupe",null],["Aneth",2,"gros bouquet",null],["Ciboules",6,null,null],["Huile",4,"c. à soupe",null],["Vermicelles de riz",300,"g",null],["Cacahuètes grillées",50,"g",null],["Mắm tôm ou nuoc-mâm au citron",4,"c. à soupe",null]],"steps":["Mariner le poisson avec curcuma, galanga, yaourt et nuoc-mâm 2 heures.","Le griller rapidement jusqu’à ce qu’il soit doré.","À table, chauffer l’huile dans une poêle sur réchaud.","Y mettre le poisson, puis l’aneth et la ciboule en tronçons; sauter 1 minute.","Servir dans des bols sur les vermicelles avec cacahuètes.","Assaisonner de mắm tôm citronné ou de nuoc-mâm."],"photo":{"file":"File:Chả cá Lã Vọng.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2f/Ch%E1%BA%A3_c%C3%A1_L%C3%A3_V%E1%BB%8Dng.jpg/1280px-Ch%E1%BA%A3_c%C3%A1_L%C3%A3_V%E1%BB%8Dng.jpg","page":"https://commons.wikimedia.org/wiki/File:Ch%E1%BA%A3_c%C3%A1_L%C3%A3_V%E1%BB%8Dng.jpg","author":"Lionel Ng from Singapore","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"som-tam-isan","country":"TH","original":"Som tam (ส้มตำ)","title":"Som tam de l’Isan (salade de papaye verte pilée)","en":"Isan som tam (green papaya salad)","es":"Som tam de Isan (ensalada de papaya verde)","desc":"Papaye verte râpée pilée au mortier avec piment, ail, citron vert, sauce de poisson, sucre de palme, tomates et haricots kilomètre, plat du nord-est thaïlandais.","cat":"Salade","diff":"easy","prep":20,"cook":0,"serv":2,"place":{"slug":"th-isan","name":"Isan","type":"region","lat":15.8,"lng":103,"summary":"Plateau du nord-est thaïlandais (Khon Kaen, Udon Thani) : som tam, larb, gai yang et riz gluant."},"ing":[["Papaye verte",300,"g","râpée en julienne"],["Ail",2,"gousses",null],["Piments oiseau",3,null,null],["Haricots kilomètre",4,null,"en tronçons"],["Tomates cerises",6,null,"coupées en deux"],["Sucre de palme",1,"c. à soupe",null],["Sauce de poisson",2,"c. à soupe",null],["Jus de citron vert",3,"c. à soupe",null],["Crevettes séchées",1,"c. à soupe",null],["Cacahuètes grillées",2,"c. à soupe",null]],"steps":["Piler l’ail et les piments au mortier.","Ajouter les haricots et les meurtrir légèrement.","Ajouter sucre de palme, sauce de poisson et citron; mélanger au pilon.","Ajouter tomates, crevettes séchées et papaye.","Piler en retournant avec une cuillère pour mêler sans écraser.","Servir avec cacahuètes, riz gluant et gai yang."],"photo":{"file":"File:Somtam kaiyang khaoniaow.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a3/Somtam_kaiyang_khaoniaow.jpg/1280px-Somtam_kaiyang_khaoniaow.jpg","page":"https://commons.wikimedia.org/wiki/File:Somtam_kaiyang_khaoniaow.jpg","author":"Takeaway","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"larb-isan","country":"TH","original":"Larb (ลาบ)","title":"Larb de l’Isan (salade de viande hachée au riz grillé et herbes)","en":"Isan larb (minced meat salad with toasted rice)","es":"Larb de Isan (ensalada de carne picada)","desc":"Porc ou poulet haché cuit, assaisonné de citron vert, sauce de poisson, piment séché et poudre de riz gluant grillé, avec échalotes, menthe et coriandre.","cat":"Salade","diff":"easy","prep":15,"cook":10,"serv":4,"place":{"slug":"th-isan","name":"Isan","type":"region","lat":15.8,"lng":103,"summary":"Plateau du nord-est thaïlandais (Khon Kaen, Udon Thani) : som tam, larb, gai yang et riz gluant."},"ing":[["Porc ou poulet haché",500,"g",